window.kbPageData["views/entry/k-c352b3325de0ff0e"] = {"key":"entry/k-c352b3325de0ff0e","state":{"route":"entry/k-c352b3325de0ff0e"},"node":{"id":"k-c352b3325de0ff0e","mode":"k","title":"全面从严治党是全党的共同政治责任","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"1.全面从严治党是全党的共同政治责任\n习近平总书记强调，管党治党的主体责任、监督责任、第一责任人责任、“一\n岗双责”等构成完整的责任链条，每一种责任都要严格落实。\n主体责任：党委（党组）负主体责任，是管党治党的“牛鼻子”。\n监督责任：纪委是党内监督的专责机关，是管党治党的重要力量，在全面从严治党\n中…","sources":[{"id":"5f43ac4a1cb0e794","label":"全面从严治党是全党的共同政治责任","topic":"党政制度与理论","category":"非时政","text":"1.全面从严治党是全党的共同政治责任\n习近平总书记强调，管党治党的主体责任、监督责任、第一责任人责任、“一\n岗双责”等构成完整的责任链条，每一种责任都要严格落实。\n主体责任：党委（党组）负主体责任，是管党治党的“牛鼻子”。\n监督责任：纪委是党内监督的专责机关，是管党治党的重要力量，在全面从严治党\n中负监督责任。\n第一责任人责任：全面从严治党第一责任人是各级党委（党组）书记，要做到重要\n工作亲自部署、重大问题亲自过问、重要环节亲自协调、重要案件亲自督办。\n“一岗双责”：领导班子其他成员履行“一岗双责”，即既要抓好分管业务工作，\n也要抓好分管领域的党风廉政建设工作，两个责任一起扛、一起落实。","source":{"doc":"41195a191a57c1c36332","first":21,"last":21,"page":21,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-c352b3325de0ff0e":[]}};
